import React from 'react';

const PropertyCard = ({ property, onNavigate }) => {
  return (
    <div className="bg-white rounded-lg shadow-md overflow-hidden">
      <div className="p-4">
        <h3 className="text-xl font-semibold mb-2">{property.property_name}</h3>
        <p className="text-gray-600 mb-2">{property.address}</p>
        <div className="flex justify-between mb-2">
          <span className="text-gray-700">{property.num_bedrooms} bd | {property.num_bathrooms} ba</span>
          <span className="font-bold">${property.price_per_person}/person</span>
        </div>
        <div className="flex justify-between text-sm text-gray-500 mb-2">
          <span>{property.furnish_status}</span>
          <span>{property.distance_to_walc} mi to campus</span>
        </div>
        {property.avg_rating && (
          <div className="flex items-center mb-2">
            <span className="text-yellow-500 mr-1">★</span>
            <span>{Number(property.avg_rating).toFixed(1)}</span>
          </div>
        )}
        <div className="flex justify-between mt-4">
          <button
            onClick={() => onNavigate('propertyDetails', property.property_id)}
            className="text-blue-600 hover:underline bg-transparent border-0 cursor-pointer"
          >
            View Details
          </button>
          <button
            onClick={() => onNavigate('propertyForm', property.property_id, true)}
            className="text-blue-600 hover:underline bg-transparent border-0 cursor-pointer"
          >
            Edit
          </button>
        </div>
      </div>
    </div>
  );
};

export default PropertyCard;
